const {decodeSignedTapeStorage,validateSignedMinute}=await import(new URL('htx-signed-tape.mjs',pathToFileURL(path.resolve('runtime/src')+'/')));
const db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),now=Date.now(),bucket=Math.floor(now/300000)*300000,id='ORIGINAL_WINDOW_DIAG:'+process.env.GITHUB_RUN_ID+':'+process.env.GITHUB_RUN_ATTEMPT;
const out={schema:'BOUNDED_POST244_TASK_AND_ORIGINAL_RAW_WINDOW_DIAGNOSIS_20261008_V1',head:process.env.GITHUB_SHA,cloud_run:process.env.GITHUB_RUN_ID,read_ts:now,sourceHTTP:0,MAIN:0,Telegram:0,task_writes:0,cache_writes:0,source_clocks_refreshed:false,actual_ENTRY:false,scope:'READ_ONLY_CURRENT_TASK_QUEUE_AND_RETAINED_RAW_MINUTES;NOT_REPUBLICATION_OR_TTL_RENEWAL'};
