if(out.FIL_task&&(out.FIL_task.due_ts!==fil.canonical_trigger.next_recheck_ts||out.FIL_task.expires_ts!==fil.canonical_trigger.expires_ts))throw Error('ORIGINAL_TASK_CLOCK_MOVED');
out.current_exact_collector_queue=await db.prepare("SELECT t.*,p.canonical_json,p.analytical_fingerprint,d.telegram_message_id\n    FROM v3_recheck_task_shadow t\n    JOIN canonical_publication_shadow p ON p.publication_id=t.publication_id AND p.contract_code=t.contract_code AND p.direction=t.direction AND p.run_id=t.run_id AND p.snapshot_id=t.snapshot_id AND p.wave_id=t.wave_id\n    JOIN v3_dispatch_publication_binding_shadow b ON b.publication_id=t.publication_id AND b.contract_code=t.contract_code AND b.direction=t.direction AND b.wave_id=t.wave_id\n    JOIN v3_telegram_dispatch_shadow d ON d.idempotency_key=b.idempotency_key AND d.state='SENT' AND d.contract=t.contract_code AND d.direction=t.direction AND d.wave_id=t.wave_id\n    JOIN v3_user_lifecycle_shadow l ON l.contract=t.contract_code AND l.direction=t.direction AND l.wave_id=t.wave_id AND l.rules_version=b.rules_version AND l.status=b.lifecycle_event AND l.observation_ts=p.observed_ts\n    WHERE t.state='PENDING' AND t.due_ts<=?1 AND b.lifecycle_event IN ('OBSERVE','WAIT')\n      AND (CASE WHEN json_valid(t.last_result) THEN COALESCE(json_extract(t.last_result,'$.last_bucket'),0) ELSE 0 END)<?2\n    ORDER BY t.updated_ts ASC,t.due_ts ASC LIMIT 2").bind(now,bucket).all();bound();
out.queue_identity_checks=(out.current_exact_collector_queue?.results||[]).map(t=>{let c;try{c=JSON.parse(t.canonical_json);}catch{return{task_id:t.task_id,status:'INVALID_CANONICAL_JSON'};}const copy={...c};delete copy.analytical_fingerprint;const fp=sha(JSON.stringify(stable(copy))),msg=String(t.telegram_message_id??''),reasons=[];if(!/^[1-9][0-9]*$/.test(msg)||!Number.isSafeInteger(Number(msg)))reasons.push('POSITIVE_MESSAGE_ID_REQUIRED');if(fp!==t.analytical_fingerprint||fp!==c.analytical_fingerprint)reasons.push('EXACT_FINGERPRINT_REQUIRED');if(c.metadata?.contract!==t.contract_code||c.run_id!==t.run_id||c.snapshot_id!==t.snapshot_id||c.direction!==t.direction||c.trigger?.next_recheck_ts!==t.due_ts||c.trigger?.expires_ts!==t.expires_ts)reasons.push('EXACT_ORIGINAL_TASK_CANONICAL_TUPLE');return{task_id:t.task_id,contract:t.contract_code,publication_id:t.publication_id,expires_ts:t.expires_ts,original_TTL_expired:now>=t.expires_ts,status:reasons.length?'COLLECTOR_WOULD_SKIP_IDENTITY':'COLLECTOR_IDENTITY_VALID',reasons};});
